CREATE TABLE alembic_version ( version_num VARCHAR(32) NOT NULL, CONSTRAINT alembic_version_pkc PRIMARY KEY (version_num) );
CREATE TABLE attachment ( id INTEGER NOT NULL, thread_id TEXT NOT NULL, turn_id TEXT NOT NULL, name TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY (id), FOREIGN KEY(thread_id) REFERENCES thread (id) ON DELETE CASCADE );
CREATE TABLE "event" ( thread_id TEXT NOT NULL, position INTEGER NOT NULL, type TEXT NOT NULL, data TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY (thread_id, position), CONSTRAINT type_valid CHECK (type IN ('status', 'meta', 'tool', 'message', 'user', 'change', 'edit', 'outcome', 'question', 'login', 'queued', 'unqueue', 'queue', 'rewind', 'access', 'browser', 'compact', 'context', 'grid')), FOREIGN KEY(thread_id) REFERENCES thread (id) ON DELETE CASCADE );
CREATE TABLE message ( thread_id TEXT NOT NULL, position INTEGER NOT NULL, role TEXT NOT NULL, content TEXT, tool_calls TEXT, tool_call_id TEXT, turn_id TEXT, created_at INTEGER NOT NULL, PRIMARY KEY (thread_id, position), CONSTRAINT role_valid CHECK (role IN ('system', 'user', 'assistant', 'tool')), FOREIGN KEY(thread_id) REFERENCES thread (id) ON DELETE CASCADE );
CREATE TABLE "preference" ( id INTEGER NOT NULL, reasoning TEXT, max_steps INTEGER NOT NULL, workspace TEXT, workspace_notes TEXT, updated_at INTEGER NOT NULL, provider TEXT DEFAULT 'copilot' NOT NULL, notify INTEGER DEFAULT 0 NOT NULL, tab_badge INTEGER DEFAULT 1 NOT NULL, full_name TEXT, instructions TEXT, PRIMARY KEY (id), CONSTRAINT reasoning_valid CHECK (reasoning IS NULL OR reasoning IN ('none', 'low', 'medium', 'high', 'xhigh', 'max')), CONSTRAINT notify_valid CHECK (notify IN (0, 1)), CONSTRAINT max_steps_valid CHECK (max_steps BETWEEN 1 AND 500), CONSTRAINT single_row CHECK (id = 1), CONSTRAINT tab_badge_valid CHECK (tab_badge IN (0, 1)) );
CREATE TABLE provider_model ( provider TEXT NOT NULL, default_model TEXT, fast_model TEXT, updated_at INTEGER NOT NULL, PRIMARY KEY (provider) );
CREATE TABLE skill ( name TEXT NOT NULL, source TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, content TEXT NOT NULL, enabled INTEGER NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY (name), CONSTRAINT source_valid CHECK (source IN ('bundled', 'custom')), CONSTRAINT enabled_valid CHECK (enabled IN (0, 1)) );
CREATE TABLE "thread" ( id TEXT NOT NULL, title TEXT NOT NULL, instance TEXT, status TEXT NOT NULL, model TEXT NOT NULL, prompt TEXT NOT NULL, pinned_at INTEGER, snoozed_until INTEGER, settled_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, provider TEXT DEFAULT 'copilot' NOT NULL, access TEXT DEFAULT 'read' NOT NULL, status_at INTEGER, seen_at INTEGER, PRIMARY KEY (id), CONSTRAINT access_valid CHECK (access IN ('read', 'ask', 'auto', 'full')), CONSTRAINT status_valid CHECK (status IN ('queued', 'running', 'waiting', 'done', 'error', 'cancelled')) );
CREATE TABLE "usage" ( id INTEGER NOT NULL, thread_id TEXT NOT NULL, model TEXT NOT NULL, kind TEXT NOT NULL, input_tokens INTEGER NOT NULL, cached_tokens INTEGER NOT NULL, cache_write_tokens INTEGER NOT NULL, output_tokens INTEGER NOT NULL, cost_nano INTEGER NOT NULL, created_at INTEGER NOT NULL, provider TEXT DEFAULT 'copilot' NOT NULL, PRIMARY KEY (id), CONSTRAINT kind_valid CHECK (kind IN ('turn', 'step', 'naming', 'guard', 'compact')), FOREIGN KEY(thread_id) REFERENCES thread (id) ON DELETE CASCADE );
CREATE INDEX attachment_by_thread ON attachment (thread_id);
CREATE INDEX thread_by_created ON thread (created_at);
CREATE INDEX thread_by_settled ON thread (settled_at);
CREATE INDEX thread_by_status ON thread (status);
CREATE INDEX usage_by_created ON usage (created_at);
CREATE INDEX usage_by_thread ON usage (thread_id);
